#!/bin/bash
set -e
cd /workspace/repo-vul/src-vul
SRC=/workspace/repo-vul/src-vul
OUT=/tmp/build
CC=gcc
CFLAGS="-fsanitize=address,undefined -fno-sanitize-recover=all -g -O1 -fno-omit-frame-pointer -DHAVE_CONFIG_H -I$SRC -I$SRC/include -I$SRC/include/libxml"
SOURCES="SAX.c entities.c encoding.c error.c parserInternals.c parser.c tree.c hash.c list.c xmlIO.c xmlmemory.c uri.c valid.c xlink.c HTMLparser.c HTMLtree.c debugXML.c xpath.c xpointer.c xinclude.c nanohttp.c nanoftp.c catalog.c globals.c threads.c c14n.c xmlstring.c buf.c xmlregexp.c xmlschemas.c xmlschemastypes.c xmlunicode.c xmlreader.c relaxng.c dict.c SAX2.c xmlwriter.c legacy.c chvalid.c pattern.c xmlsave.c xmlmodule.c schematron.c xzlib.c"
echo "Compiling libxml2..."
for f in $SOURCES; do
  $CC $CFLAGS -c $SRC/$f -o $OUT/${f%.c}.o 2> $OUT/${f%.c}.err || { echo "FAIL: $f"; tail -5 $OUT/${f%.c}.err; exit 1; }
done
echo "Creating archive..."
ar rcs $OUT/libxml2.a $OUT/*.o
echo "Compiling fuzz support..."
$CC $CFLAGS -c $SRC/fuzz/fuzz.c -o $OUT/fuzz.o 2>$OUT/fuzz.err || { echo "FAIL fuzz.c"; tail -5 $OUT/fuzz.err; exit 1; }
echo "Compiling xml fuzzer..."
$CC $CFLAGS -c $SRC/fuzz/xml.c -o $OUT/xml_fuzz.o 2>$OUT/xml_fuzz.err || { echo "FAIL xml.c"; tail -5 $OUT/xml_fuzz.err; exit 1; }
echo "Linking fuzzer driver..."
cat > $OUT/driver.c <<'DRV'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int LLVMFuzzerInitialize(int *argc, char ***argv);
int LLVMFuzzerTestOneInput(const char *data, size_t size);
int main(int argc, char **argv) {
    FILE *f;
    long sz;
    char *buf;
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 1; }
    LLVMFuzzerInitialize(&argc, &argv);
    f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END); sz = ftell(f); fseek(f, 0, SEEK_SET);
    buf = (char*)malloc(sz);
    if (fread(buf, 1, sz, f) != (size_t)sz) { perror("fread"); return 1; }
    fclose(f);
    LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
    return 0;
}
DRV
$CC $CFLAGS -c $OUT/driver.c -o $OUT/driver.o 2>$OUT/driver.err || { echo "FAIL driver"; tail -5 $OUT/driver.err; exit 1; }
$CC $CFLAGS $OUT/driver.o $OUT/xml_fuzz.o $OUT/fuzz.o $OUT/libxml2.a -lz -llzma -lm -lpthread -o $OUT/xml_fuzz 2>$OUT/link.err || { echo "FAIL link"; tail -20 $OUT/link.err; exit 1; }
echo "BUILD OK: $OUT/xml_fuzz"
EOF
